from collections import deque

def solve(x, y, visited, n, m, graph):
    queue = deque([(x, y)])
    while queue:
        new_c, new_r = queue.popleft()
        if new_c < 0 or new_c >= n or new_r < 0 or new_r >= m or visited[new_c][new_r] or graph[new_c][new_r] == '#':
            continue
        visited[new_c][new_r] = True
        queue.extend([(new_c-1, new_r), (new_c+1, new_r), (new_c, new_r-1), (new_c, new_r+1)])

