import heapq


def dijkstra(n, adj_lst, start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, node = heapq.heappop(pq)

        if d > dist[node]:
            continue

        for n, e in adj_lst[node]:
            new_dist = dist[node] + e
            if new_dist < dist[n]:
                dist[n] = new_dist
                heapq.heappush(pq, (new_dist, n))

    return dist


