import heapq

def dijkstra(n, graph):
    dist = [float('inf')] * n
    pq = [(0, 1)]  
    dist[0] = 0  
    while pq:
        du, u = heapq.heappop(pq)
        if du > dist[u - 1]:
            continue

        if u in graph:
            for v, w in graph[u]:
                alt = dist[u - 1] + w
                if alt < dist[v - 1]:
                    dist[v - 1] = alt
                    heapq.heappush(pq, (alt, v))            
    return dist

