def pow(a, b, mod):
    if b == 0:
        return 1
    if b == 1:
        return a % mod
    if b % 2 == 0:
        return pow(a, b // 2, mod) ** 2 % mod
    else:
        return pow(a, b // 2, mod) ** 2 * a % mod


